To generate a JSON schema for a standard grade-change review workflow, I'll use the JSON Schema tool. Here's the schema:

```json
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "Grade-Change Review Workflow",
  "description": "A JSON schema representing a standard grade-change review workflow",
  "type": "object",
  "properties": {
    "gradeChangeRequest": {
      "type": "object",
      "properties": {
        "studentId": {
          "type": "string",
          "description": "The unique identifier of the student"
        },
        "courseCode": {
          "type": "string",
          "description": "The code of the course for which the grade change is requested"
        },
        "originalGrade": {
          "type": "string",
          "description": "The original grade given for the course"
        },
        "requestedGrade": {
          "type": "string",
          "description": "The grade the student is requesting"
        },
        "justification": {
          "type": "string",
          "description": "The reason for the grade change request"
        },
        "submittedOn": {
          "type": "string",
          "format": "date-time",
          "description": "The date and time the request was submitted"
        }
      },
      "required": ["studentId", "courseCode", "originalGrade", "requestedGrade", "justification", "submittedOn"]
    },
    "reviewerComments": {
      "type": "object",
      "properties": {
        "reviewerId": {
          "type": "string",
          "description": "The unique identifier of the reviewer"
        },
        "comments": {
          "type": "string",
          "description": "The comments or feedback from the reviewer"
        },
        "approved": {
          "type": "boolean",
          "description": "Indicates if the grade change was approved or not"
        },
        "reviewedOn": {
          "type": "string",
          "format": "date-time",
          "description": "The date and time the review was completed"
        }
      },
      "required": ["reviewerId", "comments", "approved", "reviewedOn"]
    }
  },
  "required": ["gradeChangeRequest", "reviewerComments"]
}
```

